:root {
   --font-weight: normal;/* 🍓字体粗细，粗是bold，细是light */

   /* === 顶部导航栏 === */
   --chat-header-bg: #EFEFEFED;
   --chat-header-border: 1px solid #DADADA;
   --chat-header-title-color: #000;
   --chat-header-title-size: 16px;
   --chat-header-title-weight: 600;
   --chat-header-subtitle-color: #8e8e8e;
   --chat-header-subtitle-size: 12px;
   --chat-header-icon-color: #171717;

   --unread-bg: #D6D6D6;/*🍓未读消息背景*/

   --timestamp-color: #6E6E6E;
   --date-divider-color: #6E6E6E;
   --narration-color: #6E6E6E;
   --system-msg-color: #6E6E6E;
   --na-bg:#FBFBFBFE;
   --na-bd:0.7px solid #ECECEC;

   --trans-detached-bg: #FFF;
   --trans-detached-color: #1A1A1A;
   --trans-btn1: #B2B2B2;

   /* === 回复预览栏 === */
   --reply-bar-accent: #333;
   --reply-bar-text-color: #6E6E6E;

   --reply-detached-bg: #FBFBFBFE;
   --reply-detached-radius: 4px;
   --reply-detached-padding: 3px 7px;
   --reply-detached-border: 1px solid #ECECEC;
   --reply-detached-text-color: #6E6E6E;
   --reply-detached-name-color: #6E6E6E;
   --reply-detached-max-width: 100%;
   --reply-detached-margin-top: 5px;

   /* === 翻译内容 === */
   --translation-size: 14px;
   --translation-text-color: #515151;
   --translation-line-height: 1.2;
   --translation-padding: 10px 0 0 0;
   --translation-bg: transparent;
   --translation-radius: 0;
   --translation-shadow: none;

   /* === 我方气泡 === */
   --bubble-me-bg: #95EC69;/*背景色*/
   --bubble-me-bg-gradient: initial;
   --bubble-me-color: #000;/*字体色*/
   --bubble-me-line-height: 1.2;
   --bubble-me-padding: 10px 12px;
   --bubble-me-radius: 4px;
   --bubble-me-shadow: none;
   --bubble-me-border: none;
   --bubble-me-link-color: transparent;

   /* === 对方气泡 === */
   --bubble-them-bg: #FFF;
   --bubble-them-bg-gradient: initial;
   --bubble-them-color: #000;
   --bubble-them-line-height: 1.2;
   --bubble-them-padding: 10px 12px;
   --bubble-them-radius: 4px;
   --bubble-them-shadow: none;
   --bubble-them-border: none;
   --bubble-them-link-color: transparent;

   /* === 语音 === */
   --voice-transcription-color: #6E6E6E;
   --voice-transcription-bg: transparent;
  /* —— 容器布局 —— */
   --voice-container-gap: 3px;
   --voice-controls-gap: 0px;
  /* —— 播放按钮 —— */
   --voice-play-btn-size: 24px;
   --voice-play-btn-bg: transparent;
   --voice-btn: url("https://i.postimg.cc/kXymFms9/wu-biao-ti161-20260515061153.png");
   --voice-play-btn-border: none;
   --voice-play-btn-radius: 50%;
   --voice-play-btn-shadow: none;
   --voice-play-btn-opacity: 1;
  /* —— 波形 —— */
   --voice-waveform-height: 26px;
   --voice-waveform-gap: 2px;
   --voice-bar-min-width: 1px;
   --voice-bar-max-width: 2px;
   --voice-bar-radius: 12px;
  /* —— 时间戳 —— */
   --voice-duration-size: 11px;
   --voice-duration-weight: 600;
  /* —— 下载按钮（设 none 可隐藏） —— */
   --voice-download-display: flex;
   --voice-download-opacity: 0;

   --transfer-card-bg: #FA9D3B;
   --transfer-text-color: #FFF;
   --transfer-text-size: 18px;
   --transfer-me-amount-color: #FFF;
   --transfer-them-amount-color: #FFF;
   --transfer-text-pending-me: "你发起了一笔转账";/*❤️我方转账备注*/
   --transfer-text-pending-them: "请收款";/*❤️对方转账备注*/
   --transfer-text-success-me: "已被接收";
   --transfer-text-rejected-me: "已被退还";
   --transfer-text-success-them: "已收款";
   --transfer-text-rejected-them: "已退还";
   --transfer-text-expired: "已过期";

  --transfer-card-bg-received: #FDCE9D;
  --transfer-card-bg-expired: #E9CFB3;
  --transfer-icon-received: url('https://i.postimg.cc/j2vm895j/wu-biao-ti171-20260605210609.png');
  --transfer-icon-returned: url('https://i.postimg.cc/wjBybsW9/wu-biao-ti171-20260605211622.png');
  --transfer-icon-expired: url('https://nos.netease.com/ysf/dfbb30c0b7383f9209c03597b101adfe.png');

   /* === 输入区域 === */
   --input-area-bg: #F8F8F8ED;
   --input-area-border-top: 1px solid #E8E8E8;
   --input-area-padding: 6px 7px 10px 7px;

   /* === 🍓底栏图标 === */
   --icon-img-1: url('https://i.postimg.cc/503ZwSqw/wu-biao-ti38-20260124015919.png'); /* 加号 */
   --icon-img-2: url('https://i.postimg.cc/rFspQMFN/wu-biao-ti161-20260514123227.png'); /* 麦克风 */
   --icon-img-3: url('https://i.postimg.cc/63yswvN5/wu-biao-ti38-20260128163919.png'); /* 贴纸 */
   --icon-img-4: url('https://i.postimg.cc/ZRc1rxF8/wu-biao-ti38-20260124014355.png'); /* AI */

   /* === 输入框 === */
   --input-box-bg: #FFFFFF;
   --input-box-color: #000;
   --input-box-radius: 6px;
   --input-box-padding: 7px 2px;
   --input-box-placeholder: transparent;
   --input-box-font-size: 13px;
   --input-box-border: 0px solid #000;

   /* === 加号按钮 === */
   --plus-btn-bg: #F0F0F000;
}

/* ===== 通话美化from 🍓小Q怡🍫 宝宝 ===== */
:root {
  --call-avatar-image:
url('https://i.postimg.cc/L8NrbF7f/wu-biao-ti173-20260606111422.png');

  /* ===== 状态 ===== */
  --call-text-me-cancel:   "已取消";
  --call-text-them-reject: "对方已取消";
  --call-text-connected:   "通话时长 ";
}
.msg-videocall-card {
  width: fit-content !important;
  min-width: 0 !important;              
  max-width: 240px !important;
  padding: 7.3px 12px !important;
  border-radius: 4px !important;
  box-shadow: none !important;
  border: none !important;
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
  position: relative !important;
  cursor: default !important;
  background: var(--bubble-them-bg) !important;
}
.msg-me .msg-videocall-card {
  background: var(--bubble-me-bg) !important;
}
.msg-me .msg-videocall-card::after {
  content: "" !important;
  position: absolute !important;
  top: 15px !important;
  right: -3.5px !important;
  width: 8px !important;
  height: 8px !important;
  background: var(--bubble-me-bg) !important;
  border-radius: 1.2px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
}
.bubble-them-custom .msg-videocall-card::before,
.msg-them .msg-videocall-card::before {
  content: "" !important;
  position: absolute !important;
  top: 15px !important;
  left: -3.5px !important;
  width: 8px !important;
  height: 8px !important;
  background: var(--bubble-them-bg) !important;
  border-radius: 1.5px !important;
  transform: rotate(45deg) !important;
  z-index: -1 !important;
  display: block !important;
  visibility: visible !important;
  opacity: 1 !important;
}
.msg-videocall-card > div:first-child {
  width: 24px !important;
  height: 24px !important;
  min-width: 24px !important;
  min-height: 24px !important;
  border-radius: 0 !important;
  background: var(--call-avatar-image) center / contain no-repeat !important;
  background-color: transparent !important;
  box-shadow: none !important;
  border: none !important;
  flex-shrink: 0 !important;
  font-size: 0 !important;
  color: transparent !important;
  overflow: visible !important;
  display: block !important;
}
.msg-videocall-card > div:first-child svg {
  display: none !important;
}
.msg-me .msg-videocall-card > div:first-child {
    order: 2;
    left: auto !important;
    right: -12px !important;
    transform: scaleX(-1);
}
.msg-videocall-card > div:nth-child(2) {
  display: flex !important;
  flex-direction: row !important;
  align-items: center !important;
  justify-content: flex-start !important;
  max-width: none !important;
  gap: 4px !important;
}
.msg-videocall-card > div:nth-child(2) > div:first-child {
  font-weight: 500 !important;
  color: var(--bubble-me-color) !important;
  -webkit-text-fill-color: var(--bubble-me-color) !important;
  letter-spacing: 0 !important;
  white-space: nowrap !important;
  overflow: hidden !important;
  margin: 0 !important;
  font-size: 0 !important;
}
.bubble-them-custom .msg-videocall-card > div:nth-child(2) > div:first-child {
  color: var(--bubble-them-color) !important;
  -webkit-text-fill-color: var(--bubble-them-color) !important;
}
.msg-videocall-card > div:nth-child(2) > div:first-child::before {
  font-size: 14px !important;
  font-weight: 500 !important;
  color: var(--bubble-me-color) !important;
  -webkit-text-fill-color: var(--bubble-me-color) !important;
  content: "通话已结束" !important;
}
.bubble-me-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-me .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before {
  content: var(--call-text-me-cancel) !important;
}
.bubble-them-custom .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before,
.msg-them .msg-videocall-card.missed > div:nth-child(2) > div:first-child::before {
  content: var(--call-text-them-reject) !important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:first-child::before {
  content: var(--call-text-connected) !important;
}
.msg-videocall-card > div:nth-child(2) > div:nth-child(2),
.msg-videocall-card > div:nth-child(2) > div:nth-child(2) * {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  width: 0 !important;
  height: 0 !important;
  font-size: 0 !important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) {
  display: inline-flex !important;
  visibility: visible !important;
  opacity: 1 !important;
  width: auto !important;
  height: auto !important;
  font-size: 14px !important;
  font-weight: 500 !important;
  color: var(--bubble-me-color) !important;
  -webkit-text-fill-color: var(--bubble-me-color) !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  gap: 0 !important;
  letter-spacing: 0 !important;
}
.bubble-them-custom .msg-videocall-card.connected > div:nth-child(2) > div:first-child {
  color: var(--bubble-them-color) !important;
  -webkit-text-fill-color: var(--bubble-them-color) !important;
}
.msg-videocall-card.connected > div:nth-child(2) > div:nth-child(2) * {
  display: inline !important;
  visibility: visible !important;
  opacity: 1 !important;
  width: auto !important;
  height: auto !important;
  font-size: 14px !important;
  color: var(--bubble-me-color) !important;
  -webkit-text-fill-color: var(--bubble-me-color) !important;
}
.bubble-them-custom .msg-videocall-card > div:nth-child(2) > div:nth-child(2) * {
  color: var(--bubble-them-color) !important;
  -webkit-text-fill-color: var(--bubble-them-color) !important;
}
.msg-videocall-card > div:nth-child(3),
.msg-videocall-card > div:nth-child(3) * {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important;
  width: 0 !important;
  height: 0 !important;
}

/* 🌃夜间模式🌃 */

