:root {
  /* === 1. 我方气泡设置 === */
  --bubble-me-bg: #2D2C31;
  --bubble-me-color: #ffffff;

  /* === 2. 对方气泡透明化 === */
  --bubble-them-bg: transparent;
  --bubble-them-color: #333333;
  --bubble-them-border: none;
  --bubble-them-shadow: none;

  /* === 3. 气泡整体等比缩小 === */
  /* 通过缩小字号和常规内边距来实现等比例变小 */
  --bubble-me-font-size: 13px;
  --bubble-them-font-size: 13px;
  --bubble-me-padding: 8px 12px;
  --bubble-them-padding: 8px 1px;
}

