    --bubble-me-radius-last: 8px 3px 8px 8px;
    --bubble-me-shadow: 0 1px 2px rgba(0, 0, 0, 0.05);
    --bubble-me-border: none;
    --bubble-me-link-color: #C92A2A;
    /* === 对方气泡 (白色) === */
    --bubble-them-bg: #ffffff;
