    --input-box-font-size: 14px;
    --input-box-border: none;
    --input-caret-color: #FDB2C7;
    /* === 输入区按钮颜色 === */
    --plus-btn-color: #555555;
    --input-btn-color: #555555;
    --send-btn-color: #FDB2C7;
    --send-btn-bg: transparent;
}
/* ================================================
   我方气泡小三角（右下角 · #FDB2C7）
   ================================================ */
.bubble-me-custom {
    position: relative !important;
    overflow: visible !important;
}
.bubble-me-custom::after {
    content: "";
    position: absolute;
    width: 8px;
    height: 8px;
    bottom: 11px;
    right: -3px;
    background-color: #FDB2C7;
    transform: rotate(45deg);
    border-radius: 2px;
    z-index: 1;
    pointer-events: none;
}
.bubble-me-custom.mid::after,
.bubble-me-custom.first::after {
    display: none !important;
}
.bubble-me-custom.last::after,
.bubble-me-custom.single::after {
    display: block !important;
}
/* ================================================
   对方气泡小三角（左下角 · 白色）
   ================================================ */
.bubble-them-custom {
    position: relative !important;
    overflow: visible !important;
}
.bubble-them-custom::before {
    content: "";
    position: absolute;
    width: 8px;
    height: 8px;
    bottom: 10px;
    left: -4px;
    background-color: #ffffff;
    transform: rotate(45deg);
    border-radius: 2px;
    z-index: 1;
    pointer-events: none;
}
.bubble-them-custom.mid::before,
.bubble-them-custom.last::before {
    display: none !important;
}
.bubble-them-custom.first::before,
.bubble-them-custom.single::before {
    display: block !important;
}
